import subprocess, re, json, collections
REPO='/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill'
data=json.load(open('/tmp/utterances.json'))
branch_by_ep=collections.defaultdict(list)
for b,msgs in data.items():
    for m in msgs:
        if m['episode']:
            branch_by_ep[m['episode']].append(m)

files=subprocess.run(['git','-C',REPO,'ls-tree','-r','--name-only','origin/main'],capture_output=True,text=True).stdout.split()
eps=[f for f in files if re.match(r'^S\d+/E\d+\.md$',f)]
main_map={}
for f in sorted(eps):
    txt=subprocess.run(['git','-C',REPO,'show','origin/main:'+f],capture_output=True,text=True).stdout
    shas=re.findall(r'^Source: friend/(\w+) @ ([0-9a-f]{40})',txt,re.M)
    main_map[f[:-3]]=shas

allmissing=[]
for ep in sorted(set(list(main_map)+list(branch_by_ep))):
    mset={s for _,s in main_map.get(ep,[])}
    bset={m['sha'] for m in branch_by_ep.get(ep,[])}
    missing=bset-mset
    extra=mset-bset
    if missing or extra:
        print(ep,'main',len(mset),'branch',len(bset),'MISSING',len(missing),'EXTRA',len(extra))
        for m in branch_by_ep.get(ep,[]):
            if m['sha'] in missing:
                allmissing.append((ep,m))
print('total missing',len(allmissing))
json.dump(allmissing,open('/tmp/missing.json','w'),indent=1)

