import subprocess, re, sys, yaml
REPO='/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill'
files=[f for f in subprocess.run(['git','-C',REPO,'ls-tree','-r','--name-only','origin/main'],capture_output=True,text=True).stdout.split() if re.match(r'^S\d+/E\d+\.md$',f)]
problems=[]
for f in sorted(files):
    txt=subprocess.run(['git','-C',REPO,'show','origin/main:'+f],capture_output=True,text=True).stdout
    parts=re.split(r'^---\s*$', txt, maxsplit=2, flags=re.M)
    if len(parts)!=3 or parts[0].strip():
        problems.append((f,'frontmatter')); continue
    meta=yaml.safe_load(parts[1]) or {}
    s=meta.get('summary')
    title=meta.get('title') or ''
    if not isinstance(s,str) or not s.strip(): problems.append((f,'no summary'))
    if not title.lower().startswith('the one with '): problems.append((f,'bad title: '+title))
    if meta.get('status') not in ('ongoing','complete'): problems.append((f,'bad status'))
    body=parts[2]
    first=body.strip().split('\n')[0].strip()
    if isinstance(s,str) and first!=s.strip(): problems.append((f,'intro paragraph differs'))
    # count entries
    n=len(re.findall(r'^Source: friend/', txt, re.M))
    if n==0: problems.append((f,'no entries'))
print('files',len(files))
for p in problems: print('PROBLEM',p)
print('total problems',len(problems))
